+const filterButtons = document.querySelectorAll(".filter-button");
+const productCards = document.querySelectorAll(".product-card");
+const dealTimers = document.querySelectorAll(".deal-timer");
+const newsletterForm = document.querySelector(".newsletter-form");
+const emailField = document.querySelector("#email");
+const newsletterStatus = document.querySelector("#newsletter-status");
+
+filterButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    const selectedFilter = button.dataset.filter;
+
+    filterButtons.forEach((filterButton) => {
+      const isActive = filterButton === button;
+      filterButton.classList.toggle("is-active", isActive);
+      filterButton.setAttribute("aria-pressed", String(isActive));
+    });
+
+    productCards.forEach((card) => {
+      const shouldShow =
+        selectedFilter === "all" || card.dataset.category === selectedFilter;
+      card.classList.toggle("is-hidden", !shouldShow);
+    });
+  });
+});
+
+const formatTimeRemaining = (milliseconds) => {
+  if (milliseconds <= 0) {
+    return "Offer ended";
+  }
+
+  const totalHours = Math.floor(milliseconds / (1000 * 60 * 60));
+  const days = Math.floor(totalHours / 24);
+  const hours = totalHours % 24;
+  const minutes = Math.floor((milliseconds % (1000 * 60 * 60)) / (1000 * 60));
+
+  if (days > 0) {
+    return `${days}d ${hours}h ${minutes}m remaining`;
+  }
+
+  return `${hours}h ${minutes}m remaining`;
+};
+
+const updateDealTimers = () => {
+  const now = Date.now();
+
+  dealTimers.forEach((timer) => {
+    const deadline = new Date(timer.dataset.deadline).getTime();
+    const remaining = deadline - now;
+    timer.textContent = formatTimeRemaining(remaining);
+  });
+};
+
+if (dealTimers.length > 0) {
+  updateDealTimers();
+  window.setInterval(updateDealTimers, 60000);
+}
+
+if (newsletterForm && emailField && newsletterStatus) {
+  newsletterForm.addEventListener("submit", (event) => {
+    event.preventDefault();
+
+    const isValid = emailField.validity.valid && emailField.value.trim() !== "";
+    emailField.setAttribute("aria-invalid", String(!isValid));
+
+    if (!isValid) {
+      newsletterStatus.textContent = "Enter a valid email address to join the list.";
+      newsletterStatus.classList.remove("is-success");
